global_definitions.value:
/*
 * VRQ reserved to the test suite, it must be a plain decimal number and
 * the application must not use it.
 */
#if !defined(SB_TEST_VRQ)
#define SB_TEST_VRQ                 31
#endif

#if (SB_TEST_VRQ < 1) || (SB_TEST_VRQ > 31)
#error "invalid SB_TEST_VRQ value"
#endif

/*
 * Mask of the test VRQ.
 */
#define SB_TEST_VRQ_MASK            (1U << SB_TEST_VRQ)

/*
 * Fastcall and syscall codes not assigned by the host, they are served as
 * not implemented. The fastcall code zero is never assigned.
 */
#define SB_TEST_UNASSIGNED_FASTC    0
#define SB_TEST_UNASSIGNED_SYSC     200

/*
 * Allowed delay in host system time checks.
 */
#define SB_TEST_ALLOWED_DELAY       sbTimeMS2I(2)

extern volatile uint32_t sb_test_vrq_count;
extern volatile uint32_t sb_test_vrq_nvrq;
extern volatile uint32_t sb_test_vrq_flags;

systime_t sb_test_wait_tick(void);
msg_t sb_test_unassigned_fastcall(void);
msg_t sb_test_unassigned_syscall(void);
uint32_t sb_test_get_pending(void);

global_code.value:
/*
 * Name of the test VRQ handler.
 */
#define __SB_TEST_MK_VECTOR(n)      __sb_vector##n
#define SB_TEST_MK_VECTOR(n)        __SB_TEST_MK_VECTOR(n)

/*
 * Counter of the test VRQ activations.
 */
volatile uint32_t sb_test_vrq_count;

/*
 * Arguments received by the test VRQ handler on its last activation.
 */
volatile uint32_t sb_test_vrq_nvrq;
volatile uint32_t sb_test_vrq_flags;

/*
 * Test VRQ handler.
 */
SB_VRQ_HANDLER(SB_TEST_MK_VECTOR(SB_TEST_VRQ)) {

  CH_IRQ_PROLOGUE();

  sb_test_vrq_nvrq  = nvrq;
  sb_test_vrq_flags = flags;
  sb_test_vrq_count++;

  CH_IRQ_EPILOGUE();
}

/*
 * Delays execution until next system time tick.
 */
systime_t sb_test_wait_tick(void) {

  chThdSleep(1);
  return chVTGetSystemTime();
}

/*
 * Invokes an unassigned fastcall code.
 */
msg_t sb_test_unassigned_fastcall(void) {

  __syscall0r(SB_TEST_UNASSIGNED_FASTC);
  return (msg_t)r0;
}

/*
 * Invokes an unassigned syscall code.
 */
msg_t sb_test_unassigned_syscall(void) {

  __syscall0r(SB_TEST_UNASSIGNED_SYSC);
  return (msg_t)r0;
}

/*
 * Returns the mask of the pending VRQs without changing it.
 */
uint32_t sb_test_get_pending(void) {

  return __sb_vrq_clrwt(0U);
}

code.value:
test_print("--- Host time frequency:                ");
test_printn(sbGetFrequency());
test_println(" Hz");
test_print("--- Sandbox tick frequency:             ");
test_printn(CH_CFG_ST_FREQUENCY);
test_println(" Hz");
#if defined(PORT_USE_LOCAL_SYSTICK)
test_print("--- Sandbox local system tick:          ");
test_println(PORT_USE_LOCAL_SYSTICK == TRUE ? "yes" : "no");
#endif
test_print("--- VRQ fast path:                      ");
test_println(SB_USER_CFG_FAST_VRQ == TRUE ? "yes" : "no");
test_print("--- VRQ fast enable inline:             ");
test_println(SB_USER_CFG_FAST_VRQ_INLINE == TRUE ? "yes" : "no");
test_print("--- Test VRQ:                           ");
test_printn(SB_TEST_VRQ);
test_println("");

t0 = sbGetSystemTime();
sbSleepMilliseconds(10);
t1 = sbGetSystemTime();
test_assert(sbTimeDiffX(t0, t1) >= sbTimeMS2I(10), "too early");
test_assert(sbTimeDiffX(t0, t1) <= sbTimeMS2I(10) + SB_TEST_ALLOWED_DELAY,
            "too late");

sb_test_vrq_nvrq  = 0xFFFFFFFFU;
sb_test_vrq_flags = 0xFFFFFFFFU;
(void)__sb_vrq_setwt(SB_TEST_VRQ_MASK);
test_assert(sb_test_vrq_count == 1U, "not activated");
test_assert((sb_test_get_pending() & SB_TEST_VRQ_MASK) == 0U,
            "still pending");
test_assert(sb_test_vrq_nvrq == (uint32_t)SB_TEST_VRQ, "wrong VRQ number");
test_assert(sb_test_vrq_flags == 0U, "unexpected flags");

(void)__sb_vrq_setwt(SB_TEST_VRQ_MASK);
test_assert(sb_test_vrq_count == 0U, "activated while disabled");
test_assert((sb_test_get_pending() & SB_TEST_VRQ_MASK) != 0U,
            "not pending");

(void)__sb_vrq_seten(SB_TEST_VRQ_MASK);
test_assert(sb_test_vrq_count == 1U, "not activated");
test_assert((sb_test_get_pending() & SB_TEST_VRQ_MASK) == 0U,
            "still pending");

(void)__sb_vrq_clren(SB_TEST_VRQ_MASK);
(void)__sb_vrq_setwt(SB_TEST_VRQ_MASK);
(void)__sb_vrq_clrwt(SB_TEST_VRQ_MASK);
(void)__sb_vrq_seten(SB_TEST_VRQ_MASK);
test_assert(sb_test_vrq_count == 1U, "withdrawn request activated");

(void)__sb_vrq_seten(SB_TEST_VRQ_MASK);
chSysLock();
(void)__sb_vrq_setwt(SB_TEST_VRQ_MASK);
n = sb_test_vrq_count;
chSysUnlock();
test_assert(n == 0U, "activated while globally disabled");

test_assert(sb_test_vrq_count == 1U, "not activated");
test_assert((sb_test_get_pending() & SB_TEST_VRQ_MASK) == 0U,
            "still pending");

(void)__sb_vrq_seten(SB_TEST_VRQ_MASK);
chSysLock();
(void)__sb_vrq_setwt(SB_TEST_VRQ_MASK);
__sb_vrq_wait();
n = sb_test_vrq_count;
chSysUnlock();
test_assert(n == 0U, "activated while globally disabled");

systime_t start, end;

n = 0;
start = sb_test_wait_tick();
end = chTimeAddX(start, TIME_MS2I(1000));
do {
  (void)sbNopFastcall();
  n++;
} while (chVTIsSystemTimeWithinX(start, end));

test_print("--- Score : ");
test_printn(n);
test_println(" fastcalls/S");

systime_t start, end;

n = 0;
start = sb_test_wait_tick();
end = chTimeAddX(start, TIME_MS2I(1000));
do {
  (void)sbGetSystemTime();
  n++;
} while (chVTIsSystemTimeWithinX(start, end));

test_print("--- Score : ");
test_printn(n);
test_println(" fastcalls/S");

systime_t start, end;

n = 0;
start = sb_test_wait_tick();
end = chTimeAddX(start, TIME_MS2I(1000));
do {
  (void)sbNopSyscall();
  n++;
} while (chVTIsSystemTimeWithinX(start, end));

test_print("--- Score : ");
test_printn(n);
test_println(" syscalls/S");

systime_t start, end;

n = 0;
start = sb_test_wait_tick();
end = chTimeAddX(start, TIME_MS2I(1000));
do {
  (void)__sb_vrq_setwt(SB_TEST_VRQ_MASK);
  n++;
} while (chVTIsSystemTimeWithinX(start, end));
test_assert(sb_test_vrq_count == n, "activations mismatch");

test_print("--- Score : ");
test_printn(n);
test_println(" VRQs/S");

systime_t start, end;

n = 0;
start = sb_test_wait_tick();
end = chTimeAddX(start, TIME_MS2I(1000));
do {
  chSysLock();
  chSysUnlock();
  n++;
} while (chVTIsSystemTimeWithinX(start, end));

test_print("--- Score : ");
test_printn(n);
test_println(" lock/unlock cycles/S");
